import sys
def h(a, b):
    return sum(x != y for x, y in zip(a, b))

def solve(h12, h13, h14, h23, h24, h34):
    def check(l):
        for s1 in ['a' * l, 'b' * l]:
            for s2 in ['a' * l, 'b' * l]:
                if h(s1, s2) != h12: continue
                for s3 in ['a' * l, 'b' * l]:
                    if h(s1, s3) != h13 or h(s2, s3) != h23: continue
                    for s4 in ['a' * l, 'b' * l]:
                        if h(s1, s4) != h14 or h(s2, s4) != h24 or h(s3, s4) != h34: continue
                        return [s1, s2, s3, s4]
        return None

    for l in range(1, 100001):
        res = check(l)
        if res:
            return l, res
    return -1, []

input = sys.stdin.read().strip().split()
h12, h13, h14 = map(int, input[:3])
h23, h24 = map(int, input[3:5])
h34 = int(input[5])

result = solve(h12, h13, h14, h24, h24, h34)
if result[0] == -1:
    print(-1)
else:
    l, strings = result
    print(l)
    for s in strings:
        print(s)
